const ELEMENT_PROP_KEYS = new Set(["theme","title","url","focus","scrollLength","scrollRows","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Changelog",
  url: "remocn.dev/changelog",
  focus: 9,
  scrollLength: 58,
  scrollRows: 30,
  accent: "#3B5BFD",
  fontFamily: "Onest",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ChangelogScrollElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ChangelogScrollBase>;

const ChangelogScrollInner = forwardRef<
  HTMLDivElement,
  ChangelogScrollElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ChangelogScroll>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ChangelogScrollBase
          {...(componentProps as unknown as ComponentProps<typeof ChangelogScrollBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ChangelogScroll = Interactive.withSchema({
  Component: ChangelogScrollInner,
  componentName: "<ChangelogScroll>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
